solution.custom_set.zig:
const std = @import("std");

pub fn CustomSet(comptime T: type) type {
    return struct {
        const Self = @This();
        items: std.array_list.Managed(T),
        pub fn init(allocator: std.mem.Allocator, values: []const T) !Self {
            var result = Self{.items = std.array_list.Managed(T).init(allocator)};
            errdefer result.deinit();
            for (values) |v| try result.add(v);
            return result;
        }
        pub fn deinit(self: *Self) void { self.items.deinit(); }
        pub fn isEmpty(self: Self) bool { return self.items.items.len == 0; }
        pub fn contains(self: Self, value: T) bool {
            for (self.items.items) |v| if (std.meta.eql(v,value)) return true;
            return false;
        }
        pub fn add(self: *Self, value: T) !void { if (!self.contains(value)) try self.items.append(value); }
        pub fn isSubset(self: Self, other: Self) bool {
            for (self.items.items) |v| if (!other.contains(v)) return false;
            return true;
        }
        pub fn isDisjoint(self: Self, other: Self) bool {
            for (self.items.items) |v| if (other.contains(v)) return false;
            return true;
        }
        pub fn eql(self: Self, other: Self) bool { return self.items.items.len == other.items.items.len and self.isSubset(other); }
        pub fn intersection(self: Self, other: Self) !Self {
            var result = try Self.init(self.items.allocator,&.{}); errdefer result.deinit();
            for (self.items.items) |v| if (other.contains(v)) { try result.add(v); };
            return result;
        }
        pub fn difference(self: Self, other: Self) !Self {
            var result = try Self.init(self.items.allocator,&.{}); errdefer result.deinit();
            for (self.items.items) |v| if (!other.contains(v)) { try result.add(v); };
            return result;
        }
        pub fn unionWith(self: Self, other: Self) !Self {
            var result = try Self.init(self.items.allocator,self.items.items); errdefer result.deinit();
            for (other.items.items) |v| try result.add(v);
            return result;
        }
    };
}

tests.test_custom_set.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("custom_set.zig");

test "set membership, duplicate elimination and all algebra" {
    const S = m.CustomSet(i32);
    var empty = try S.init(a,&.{}); defer empty.deinit();
    var left = try S.init(a,&.{1,2,2,3}); defer left.deinit();
    var right = try S.init(a,&.{3,4}); defer right.deinit();
    var reordered = try S.init(a,&.{3,2,1}); defer reordered.deinit();
    try t.expect(empty.isEmpty()); try t.expect(!left.isEmpty());
    try t.expect(left.contains(2)); try t.expect(!left.contains(4));
    try t.expect(empty.isSubset(left)); try t.expect(!left.isSubset(empty));
    try t.expect(empty.isDisjoint(left)); try t.expect(!left.isDisjoint(right));
    try t.expect(left.eql(reordered)); try t.expect(!left.eql(right));
    try left.add(2); try t.expect(left.eql(reordered));
    var intersection = try left.intersection(right); defer intersection.deinit();
    try t.expectEqualSlices(i32,&.{3},intersection.items.items);
    var difference = try left.difference(right); defer difference.deinit();
    try t.expectEqualSlices(i32,&.{1,2},difference.items.items);
    var combined = try left.unionWith(right); defer combined.deinit();
    try t.expectEqualSlices(i32,&.{1,2,3,4},combined.items.items);
    var none = try empty.intersection(right); defer none.deinit(); try t.expect(none.isEmpty());
}
